\begin{lemma}
\label{ch02-lem-neckpinch-L-evolution}
\source{chow-knopf-ricci-flow:page-0057}
\dcref{Lemma 2.25}
\group{neckpinch}

The curvature quantity \(L=K_1\) evolves by
\[
L_t=\Delta L+2\frac{\psi_s}{\psi}L_s+2\bigl[K^2+(n-1)L^2\bigr].
\]
\end{lemma}

